#!/usr/bin/env python3
"""Write LICENSE.md, ATTRIBUTION.md and README.md of every themes/openkylin* package.

Usage: python3 -I package_docs.py REPO_ROOT [--check]
"""
import pathlib, sys

root = pathlib.Path(sys.argv[1]); check = "--check" in sys.argv
V = {
 "openkylin": ("openKylin (UKUI v11)", "`v11`", "classic UKUI taskbar on the bottom edge (it can sit on any edge)", "`ukui-icon-theme-default`", "`dark-sense`", "daybreak blue `#3676F5`, 12 px window corners, light and dark"),
 "openkylin-islands": ("openKylin (UKUI islands)", "`v11`", "UKUI's three-island floating taskbar (Dux `islands`), bottom edge", "`ukui-icon-theme-default`", "`dark-sense`", "the v11 palettes; island radius 12, margin 8, gap 8"),
 "openkylin-light-seeking": ("openKylin (Light-Seeking 寻光)", "`Light-Seeking`", "classic UKUI taskbar on the bottom edge (it can sit on any edge)", "`ukui-icon-theme-default`", "`dark-sense`", "azure `#3790FA`, 12 px corners, opaque grey menus"),
 "openkylin-heyin": ("openKylin (HeYin 和印)", "`HeYin`", "classic UKUI taskbar on the bottom edge (it can sit on any edge)", "`ukui-icon-theme-fashion`", "`DMZ-White`", "jam purple `#8926EB`, 12 px corners; upstream defaults to dark"),
 "openkylin-classic": ("openKylin (Classic 启典)", "`Classic`", "classic UKUI taskbar on the bottom edge (it can sit on any edge)", "`ukui-icon-theme-classical`", "`dark-sense`", "square corners everywhere, flat solid `#3790FA` accent"),
}
LIC = 'MIT License (the manifest and documentation of this package)\n\nCopyright (c) the Decebal contributors\n\nPermission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation\nfiles (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy,\nmodify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the\nSoftware is furnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all copies or substantial portions of the\nSoftware.\n\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE\nWARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR\nCOPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE,\nARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n\nWhat this licence does NOT cover: openKylin / UKUI artwork (icon packs, cursor themes), the openKylin and Wallhaven\nwallpapers, and the trademarks "openKylin", "UKUI" and "Kylin". None of those is inside this package. See ATTRIBUTION.md.\n'
ATTR = '# Attribution: @NAME@\n\nThis package contains `theme.toml` (colour values, metrics and panel choices), two small widget definitions, this note, the licence and **one upstream image**:\n`icons/kylin-startmenu.png` (128 x 128), the UKUI start button\'s artwork (`kylin-startmenu`, the icon the `ukui-menu-starter` widget draws), copied unchanged from\n`icons/ukui-icon-theme-@PACK@/128x128/apps/kylin-startmenu.png` of <https://github.com/openkylin/openkylin-theme> at commit `3c78d714aa8fac723c9a5360bd54484789a647ab`\n(git blob `@BLOB@`, verified by `tests/openkylin_port.py`). Declared licence of that repository: GPL-3 (`debian/copyright`); the icon index says part of the artwork is "from moka":\nthat provenance is **unresolved** (not researched, not assumed). The openKylin mark is also a brand of its owners: it is shown only as the identity of the replicated desktop.\nIt is bundled so the start button is the real mark without an icon pack; the pack itself is never bundled. No other upstream code, icon, cursor, wallpaper, font or asset is copied.\n\n## Where the design comes from\n\n* UKUI global theme @GT@ from <https://github.com/openkylin/ukui-globaltheme>, commit\n  `83cb8ff8f113e4002681401ac9da97997f440968` (branch `openkylin/huanghe`, 2025-04-08): `theme.conf` and the light/dark CSS\n  token tables. The declared licence of that repository is GPL-3.0+ (`debian/copyright`). The colour *values* and\n  radii are design facts measured from those tables; the mapping tool and this manifest are independent MIT work, no GPL\n  implementation code is used.\n* Panel geometry and widget order: <https://github.com/openkylin/ukui-panel>, commit\n  `3429618a48b7049e87b1a1857599534cc0ae76ab` (GPL-3.0+ / Expat). Measured, not copied.\n* Desktop time widget (`widgets/ukui-time-*.toml`): <https://github.com/openkylin/ukui-system-appwidget> (GPL, `time.qml`), commit\n  `059a328736edd8556bd4b1d6b3f21b9394dcdda9`: sizes and layout measured; the files here are independent MIT definitions.\n* Window decoration measurements: <https://github.com/openkylin/kwin> (`src/plugins/kdecorations/ukui`, LGPL-3), commit\n  `01bf91445b61470fce0c7ac6b0f47daa2f8dc9d0`; the rdwm styles themselves come from the decorations owner.\n\nExact pins, declared licences and verified tree object ids: `assets/desktop-ports/openkylin/sources.json` and\n`asset-packs.toml` (the shared asset-pack catalogue) in the Decebal repository.\n\n## Suggested but separate\n\n* Icon pack @ICONS@ and cursor theme @CUR@ are the upstream suggestion of this global theme. They are **installed by the shared decebal asset installer from the pinned\n  upstream commit** (`decthemectl assets install`, tree-verified) (GPL-3 for the icons; `dark-sense` GPL-3; `DMZ-White` CC-BY-SA-3.0, Copyright 2007-2010\n  Novell, Inc.) and are never bundled. They stay independently selectable in Settings.\n* Wallpapers: photographs recommended in `assets/desktop-ports/openkylin/wallpapers.json` (Wallhaven). Authorship and licence of\n  those photographs are **unknown**; nothing is redistributed. This package sets no wallpaper.\n\n"openKylin", "UKUI" and "Kylin" belong to their respective owners. This package is an independent adaptation and does not\nimply endorsement.\n'
README = '# @NAME@\n\nAn adaptation of the real UKUI desktop design from the openKylin project (see [ATTRIBUTION.md](ATTRIBUTION.md)), built on the\nshared Decebal panel framework (`min_shell_version = "0.3.0"`).\n\n* **Global theme:** @GT@ (@LOOK@). Light and dark palettes are derived from UKUI\'s resolved token tables; the mapping is\n  documented in `docs/desktop-ports/openkylin/palette.md`.\n* **Panel:** @PANEL@. Every applet in the shared registry can still be turned on or off, and the edge changed, in\n  Settings → Panels; the package only supplies defaults and never overwrites your choices.\n* **Window decoration:** the measured native `openkylin` / `openkylin-dark` rdwm styles (38 px header, 30 px buttons, radius 12) when your running window manager lists them,\n  otherwise an honest fallback with a persistent warning (see the port documentation).\n* **Branding:** the start button is UKUI\'s own `kylin-startmenu` mark (the @PACK@ pack\'s artwork, bundled as `icons/kylin-startmenu.png`, see ATTRIBUTION.md); it does not depend on an installed icon pack.\n* **Suggested separately (never forced):** icons @ICONS@, cursor @CUR@, photographs from the Wallpaper → For this theme list.\n* **Fonts:** `Noto Sans CJK SC` then `Noto Sans` (your system fonts; none is bundled).\n'
_D, _F, _C = ("default", "adbe8bd46bcb314dd8eaff1e1ec198409b27b856"), ("fashion", "4dfa94880821aa60e3ecd9860eb9a6dbeda431cd"), ("classical", "379a20c9cd81c6e5ff929b6523401e1986c80cb8")
PACK = {"openkylin": _D, "openkylin-islands": _D, "openkylin-light-seeking": _D, "openkylin-heyin": _F, "openkylin-classic": _C}
bad = 0
for pid, (name, gt, panel, icons, cur, look) in V.items():
    sub = lambda t: t.replace("@NAME@", name).replace("@GT@", gt).replace("@PANEL@", panel).replace("@ICONS@", icons).replace("@CUR@", cur).replace("@LOOK@", look).replace("@PACK@", PACK[pid][0]).replace("@BLOB@", PACK[pid][1])
    d = root / "themes" / pid
    for fn, text in {"LICENSE.md": LIC, "ATTRIBUTION.md": sub(ATTR), "README.md": sub(README)}.items():
        f = d / fn
        if check:
            if not f.exists() or f.read_text() != text: print("DRIFT", f); bad += 1
        else:
            d.mkdir(parents=True, exist_ok=True); f.write_text(text)
sys.exit(1 if bad else 0)
